  box-sizing: border-box;
  height: 100%;
  width: 100%;
  padding: 16px;
  background: #A7C7E7;
  color: #ffffff;
  border-radius: 20px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 10px;
  font-family: inherit;
}

.tb-time .title {
  text-align: center;
  font-size: 16px;
  font-weight: 600;
  line-height: 20px;
}

.tb-time .row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);   /* 3 data in one row */
  gap: 12px;
}

.tb-time .cell {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  text-align: center;
  min-width: 0;
}

.tb-time .label,
.tb-time .value {
  display: block;
  width: 100%;
}

.tb-time .label {
  height: 16px;
  line-height: 16px;
  font-size: 12px;
  opacity: 0.9;
}

.tb-time .value {
  height: 30px;
  line-height: 30px;
  font-size: 22px;
  font-weight: 600;
}

.tb-led {
  box-sizing: border-box;
  height: 100%;
  width: 100%;
  padding: 16px;
  background: none;                 /* no background */
  color: #ffffff;
  border-radius: 0;
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  gap: 16px;
  font-family: inherit;
}

/* LED on the left */
.tb-led .led {
  position: relative;
  flex: 0 0 40px;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.6), 0 0 12px rgba(0, 0, 0, 0.25);
}

.tb-led .led span {
  position: absolute;
  top: 0; right: 0; bottom: 0; left: 0;
  border-radius: 50%;
  transition: opacity 0.3s;
}

.tb-led .led .g { background: #2ecc71; }   /* green */
.tb-led .led .y { background: #f1c40f; }   /* yellow */
.tb-led .led .r { background: #e74c3c; }   /* red */

/* Text on the right: all three texts share one grid cell */
.tb-led .txt {
  display: grid;
  min-width: 0;
}

.tb-led .txt span {
  grid-area: 1 / 1;
  font-size: 22px;
  font-weight: 600;
  line-height: 44px;                /* same height as the LED */
  white-space: nowrap;
  transition: opacity 0.3s;
}

