.tb-seven {
  box-sizing: border-box;
  height: 100%;
  width: 100%;
  padding: 0;
  background: none;
  display: grid;
  grid-template-columns: repeat(7, 1fr);   /* 7 equal columns */
  gap: 0;
  align-items: start;
  font-family: inherit;
}

.tb-seven .cell {
  box-sizing: border-box;
  padding: 0 2px;                           /* small gap between the titles */
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 0;
}

/* title: scales with the column width, no background */
.tb-seven .ttl {
  display: block;
  width: 100%;
  height: auto;
  background: none;
}

.tb-seven .ttl text {
  fill: #1b1f3b;                            /* dark text, as in your screenshot */
  font-weight: 600;
  font-family: inherit;
}

/* LED, fixed 30 px high box, directly under the title */
.tb-seven .dotbox {
  height: 30px;
  margin-top: 0;                            /* title sits right above the LED */
  display: flex;
  align-items: center;
  justify-content: center;
}

.tb-seven .dot {
  position: relative;
  width: 24px;
